    val kinds = spec.game.runtime.kinds
    val cfg = GeneratedRuntimeConfig.config
    val loop = session.loop
    val seed = session.seed
    val context = LocalContext.current
    val prefs = remember { context.getSharedPreferences("monstera", Context.MODE_PRIVATE) }
    var best by remember { mutableLongStateOf(prefs.getLong(BEST_KEY, 0L)) }
    var started by remember { mutableStateOf(false) }
    var frames by remember { mutableLongStateOf(0L) }  // read by the Canvas so it redraws every frame
    var viewSize by remember { mutableStateOf(IntSize.Zero) }
    val worldW = cfg.worldWidth / RAW_ONE
    val worldH = cfg.worldHeight / RAW_ONE
    val density = LocalDensity.current
    val insetTop = WindowInsets.safeDrawing.getTop(density).toFloat()  // status bar or cutout; the HUD sits below it
    val insetBottom = WindowInsets.safeDrawing.getBottom(density).toFloat()  // gesture or navigation bar; the world ends above it
    val layout = Layout(viewSize.width.toFloat(), viewSize.height.toFloat(), worldW, worldH, insetTop, insetBottom)
    val tracker = remember(loop) { EffectTracker(kinds.map { effectOf(it.effect) }, WorldBox(0f, 0f, worldW, worldH)) }
    val glyphPaint = remember { Paint(Paint.ANTI_ALIAS_FLAG).apply { textAlign = Paint.Align.CENTER } }
    val popupPaint = remember { Paint(Paint.ANTI_ALIAS_FLAG).apply { textAlign = Paint.Align.CENTER; isFakeBoldText = true } }

    LaunchedEffect(loop) {
        var last = 0L
        var logged = false
        while (true) {
            withFrameNanos { now ->
                val elapsed = if (last == 0L) 0L else now - last
                loop.frame(elapsed)
                last = now
                frames++
                val w = loop.world
                tracker.observe(w.score, w.lives, w.snapshot().map {
                    val k = cfg.kinds[it.kind]
                    Tracked(it.id.toLong(), it.kind, WorldBox(it.x / RAW_ONE, it.y / RAW_ONE, k.width / RAW_ONE, k.height / RAW_ONE))
                })
                tracker.advance(minOf(elapsed, 100_000_000L) / 1_000_000_000f)
                if (!logged && w.tick >= 60u) {
                    logged = true
                    Log.i(TAG, "runtime ticks=${w.tick} hash=${w.stateHash().toString(16).padStart(16, '0')} seed=$seed")
                }
            }
        }
    }

    check(frames >= 0L)  // reading the frame counter here makes the HUD and the cards recompose every frame
    val ended = loop.world.ended
    LaunchedEffect(loop, ended, started) {
        if (started && ended && loop.world.score > best) {
            best = loop.world.score
            prefs.edit().putLong(BEST_KEY, best).apply()
        }
    }

    fun send(event: InputEvent) { if (started) loop.submit(event) }

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(hexColor(palette.background))
            .onSizeChanged { viewSize = it }
            .semantics { contentDescription = "Game view" }
            .pointerInput(loop) {
                detectTapGestures(
                    onPress = {
                        send(InputEvent(InputType.PRESS))
                        tryAwaitRelease()
                        send(InputEvent(InputType.RELEASE))
                    },
                    onTap = {
                        if (!started) {
                            started = true
                            onRestart()  // the first tap starts a fresh session with a fresh seed
                        } else if (loop.world.ended) onRestart() else send(InputEvent(InputType.TAP))
                    },
                )
            }
            .pointerInput(loop, spec.game.input.scheme) {
                var total = Offset.Zero
                detectDragGestures(
                    onDragStart = { total = Offset.Zero },
                    onDragEnd = {
                        if (spec.game.input.scheme == InputScheme.LANES && abs(total.x) > abs(total.y) && abs(total.x) > TAP_SLOP_PX) {
                            // One lane per swipe: a drag of +-swipeSpeed (the lane step) in the swipe direction.
                            val step = spec.game.input.swipeSpeed.toLong()
                            send(InputEvent(InputType.DRAG, if (total.x > 0f) step else -step, 0L))
                        } else if (spec.game.input.scheme == InputScheme.SWIPE && maxOf(abs(total.x), abs(total.y)) > TAP_SLOP_PX) {
                            val dir = if (abs(total.x) > abs(total.y)) {
                                if (total.x > 0f) Direction.RIGHT else Direction.LEFT
                            } else {
                                if (total.y > 0f) Direction.DOWN else Direction.UP
                            }
                            send(InputEvent(InputType.SWIPE, dir = dir))
                        }
                    },
                ) { _, amount ->
                    total += amount
                    if (spec.game.input.scheme != InputScheme.SWIPE && spec.game.input.scheme != InputScheme.LANES && layout.scale > 0f) {
                        send(InputEvent(InputType.DRAG, (amount.x / layout.scale * RAW_ONE).roundToLong(), (amount.y / layout.scale * RAW_ONE).roundToLong()))
