            val world = layout.world
            val alpha = loop.alpha / RAW_ONE
            val s = layout.scale
            // Everything inside the world is clipped to the world rectangle; the HUD bar and the letterbox stay clear.
            clipRect(world.x, world.y, world.right, world.bottom) {
                translate(tracker.shakeX() * s, tracker.shakeY() * s) {
                    for (e in loop.world.snapshot()) {
                        val k = cfg.kinds[e.kind]
                        // Interpolated for display only; the simulation state is never changed by drawing.
                        val box = WorldBox((e.x + e.vx * alpha) / RAW_ONE, (e.y + e.vy * alpha) / RAW_ONE, k.width / RAW_ONE, k.height / RAW_ONE)
                        val px = layout.toScreen(box)
                        if (layout.visible(box) == null) continue
                        val kind = kinds[e.kind]
                        if (kind.glyph.isEmpty()) {
                            drawRect(hexColor(kind.color), Offset(px.x, px.y), Size(px.w, px.h))
                        } else {
                            glyphPaint.textSize = Texts.glyphSize(px)
                            drawIntoCanvas { c ->
                                val fm = glyphPaint.fontMetrics
                                c.nativeCanvas.drawText(kind.glyph, px.x + px.w / 2f, px.y + px.h / 2f - (fm.ascent + fm.descent) / 2f, glyphPaint)
                            }
                        }
                    }
                    for (p in tracker.particles) {
                        val c = layout.toScreen(WorldBox(p.x, p.y, p.size, p.size))
                        drawRect(hexColor(kinds[p.kind].color).copy(alpha = p.alpha.coerceIn(0f, 1f)), Offset(c.x - c.w / 2f, c.y - c.h / 2f), Size(c.w, c.h))
                    }
                    for (r in tracker.rings) {
