                        drawCircle(hexColor(kinds[r.kind].color).copy(alpha = r.alpha.coerceIn(0f, 1f)), r.radius * s, Offset(c.x, c.y), style = Stroke(width = 6f))
                    }
                    for (p in tracker.popups) {
