                        popupPaint.textSize = maxOf(28f, 56f * s)
                        popupPaint.color = hexColor(palette.accent).copy(alpha = p.alpha.coerceIn(0f, 1f)).toArgb()
                        drawIntoCanvas { it.nativeCanvas.drawText(p.text, c.x, c.y, popupPaint) }
                    }
                }
                if (tracker.flash > 0f) {
                    drawRect(Color.Red.copy(alpha = tracker.flash * 0.35f), Offset(world.x, world.y), Size(world.w, world.h))
                }
            }
            drawRect(hexColor(palette.primary), Offset(world.x, world.y), Size(world.w, world.h), style = Stroke(width = 4f))
        }

        val w = loop.world
        val hudHeight = with(density) { layout.hudHeight.toDp() }
        val insetDp = with(density) { insetTop.toDp() }
        val hudText = with(density) { (layout.hudHeight * 0.45f).toSp() }
        Row(
            modifier = Modifier.fillMaxWidth().padding(top = insetDp).height(hudHeight).padding(horizontal = 16.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Text(Texts.score(spec.game.hud.scoreLabel, w.score), color = hexColor(palette.accent), fontSize = hudText, fontWeight = FontWeight.Bold)
            if (!verified) Text("SPEC MISMATCH", color = Color.Red, fontSize = hudText)
            Text(Texts.lives(spec.game.hud.lifeGlyph, w.lives), color = hexColor(palette.accent), fontSize = hudText, fontWeight = FontWeight.Bold)
        }

        if (!started || w.ended) {
            Box(modifier = Modifier.fillMaxSize().padding(top = insetDp + hudHeight), contentAlignment = Alignment.Center) {
                Column(
                    modifier = Modifier.background(Color.Black.copy(alpha = 0.7f), RoundedCornerShape(16.dp)).padding(horizontal = 32.dp, vertical = 24.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
